import json,sys,html
root=Path('/Users/adnanyonathan/Documents/Codex/2026-09-20/wh/outputs/iphone-golf-simulator');folder=Path(sys.argv[1]) if len(sys.argv)>1 else root/'proof/full-visual-overhaul/golf-pass-8'
