output=root/'proof/full-visual-overhaul/golf/catalog-review.html';rows=json.loads((output.parent/'catalog-coverage-source.json').read_text());sections=[];matrix=[]
for r in rows:
 n=r['hole'];present=[];shots=[]
 for shot in ['tee','approach','putting','aerial','preview','gameplay']:
  p=folder/f'hole{n:02}_{shot}.png';available=p.exists();present.append(available)
