 audit=folder/f'hole{n:02}_audit.json';data=json.loads(audit.read_text()) if audit.exists() else {}
 summary=(f'Frustum geometry {data.get("cameraMeshTriangles","pending"):,} triangles' if isinstance(data.get('cameraMeshTriangles'),int) else 'Frustum geometry pending')+f'; {data.get("cameraMaterialPasses","pending")} material passes. Physics comparison and published automatic-frame costs are separate gates.'
 matrix.append({'hole':n,'captured_shots':sum(present),'expected_shots':6,'audit_available':audit.exists(),'visual_acceptance':'PASS parent World18 map review within documented concept-partial limits; final audience-inclusive counters separate','capture_folder':str(folder.relative_to(root))})
